import { once } from 'node:events'

const TRACKER = Symbol('unpipe.tracker')

function isStream(value) {
  return value !== null && typeof value === 'object' && typeof value.pipe === 'function'
}

function trackerOf(readable) {
  return readable[TRACKER]
}

export function trackDestinations(readable) {
  if (!isStream(readable)) {
    throw new TypeError('trackDestinations expects a readable stream')
  }
  if (trackerOf(readable)) return trackerOf(readable)

  const destinations = new Set()
  const originalPipe = readable.pipe
  const originalUnpipe = readable.unpipe

  const onUnpipe = (_source, destination) => {
    if (destination) destinations.delete(destination)
    else destinations.clear()
  }

  readable.on('unpipe', onUnpipe)

  readable.pipe = function patchedPipe(destination, options) {
    const result = originalPipe.call(this, destination, options)
    if (isStream(destination)) {
      destinations.add(destination)
      const drop = () => destinations.delete(destination)
      destination.once('close', drop)
      destination.once('finish', drop)
      destination.once('error', drop)
    }
    return result
  }

  const tracker = {
    get destinations() {
      return [...destinations]
    },
    get size() {
      return destinations.size
    },
    unpipeAll() {
      originalUnpipe.call(readable)
      destinations.clear()
      return readable
    },
    stopTracking() {
      readable.off('unpipe', onUnpipe)
      readable.pipe = originalPipe
      delete readable[TRACKER]
    },
  }

  Object.defineProperty(readable, TRACKER, {
    value: tracker,
    configurable: true,
  })

  return tracker
}

export function unpipeAll(readable) {
  if (!isStream(readable)) {
    throw new TypeError('unpipeAll expects a readable stream')
  }

  const tracker = trackerOf(readable)
  if (tracker) {
    tracker.unpipeAll()
  } else {
    readable.unpipe()
  }

  return readable
}

import http from 'node:http'
import { Readable } from 'node:stream'
import { trackDestinations } from './unpipe.js'

const PORT = Number(process.env.PORT ?? 3000)
const TICK_MS = Number(process.env.TICK_MS ?? 1000)

let seq = 0

const ticks = new Readable({
  read() {
    if (this._timer) return
    this._timer = setInterval(() => {
      seq += 1
      this.push(`data: ${JSON.stringify({ seq, time: new Date().toISOString() })}\n\n`)
    }, TICK_MS)
  },
  destroy(error, callback) {
    clearInterval(this._timer)
    callback(error)
  },
})

const connections = trackDestinations(ticks)

const server = http.createServer((req, res) => {
  switch (req.url) {
    case '/health':
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ ok: true, destinations: connections.size }))
      return

    case '/events':
      res.writeHead(200, {
        'content-type': 'text/event-stream',
        'cache-control': 'no-cache',
        connection: 'keep-alive',
      })
      ticks.pipe(res)
      req.on('close', () => ticks.unpipe(res))
      return

    case '/disconnect-all': {
      const detached = connections.size
      connections.unpipeAll()
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ ok: true, detached }))
      return
    }

    default:
      res.writeHead(404, { 'content-type': 'text/plain' })
      res.end('not found')
  }
})

server.listen(PORT, () => {
  console.log(`server listening on http://localhost:${PORT}`)
})

export { server, ticks, connections }

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { PassThrough } from 'node:stream'
import { trackDestinations, unpipeAll } from '../src/unpipe.js'

function collect(stream) {
  const chunks = []
  stream.on('data', (chunk) => chunks.push(chunk.toString()))
  return chunks
}

test('tracks every destination of a readable', () => {
  const source = new PassThrough()
  const tracker = trackDestinations(source)
  const a = new PassThrough()
  const b = new PassThrough()

  source.pipe(a)
  source.pipe(b)

  assert.equal(tracker.size, 2)
  assert.deepEqual(new Set(tracker.destinations), new Set([a, b]))
})

test('unpipeAll detaches every destination', () => {
  const source = new PassThrough()
  const tracker = trackDestinations(source)
  const a = new PassThrough()
  const b = new PassThrough()
  source.pipe(a)
  source.pipe(b)

  const aSeen = collect(a)
  const bSeen = collect(b)

  tracker.unpipeAll()

  assert.equal(tracker.size, 0)

  source.write('after-unpipe')

  assert.deepEqual(aSeen, [])
  assert.deepEqual(bSeen, [])
})

test('unpipeAll works on an untracked stream', () => {
  const source = new PassThrough()
  const a = new PassThrough()
  const b = new PassThrough()
  source.pipe(a)
  source.pipe(b)

  const aSeen = collect(a)
  const bSeen = collect(b)

  assert.equal(unpipeAll(source), source)

  source.write('after-unpipe')

  assert.deepEqual(aSeen, [])
  assert.deepEqual(bSeen, [])
})

test('unpipeAll is idempotent and returns the readable', () => {
  const source = new PassThrough()
  const tracker = trackDestinations(source)
  source.pipe(new PassThrough())

  assert.equal(tracker.unpipeAll(), source)
  assert.equal(tracker.unpipeAll(), source)
  assert.equal(tracker.size, 0)
})

test('destinations removed after a destination error', () => {
  const source = new PassThrough()
  const tracker = trackDestinations(source)
  const destination = new PassThrough()
  source.pipe(destination)

  assert.equal(tracker.size, 1)

  destination.destroy(new Error('boom'))
  destination.emit('error', new Error('boom'))

  assert.equal(tracker.size, 0)
})

test('stopTracking restores the original pipe', () => {
  const source = new PassThrough()
  const originalPipe = source.pipe
  const tracker = trackDestinations(source)

  tracker.stopTracking()

  assert.equal(source.pipe, originalPipe)
  assert.equal(trackDestinations(source).size, 0)
})

